import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');const dir='artifacts/replies-4pm-20261019';await fs.mkdir(dir,{recursive:true});const source=JSON.parse(await fs.readFile('artifacts/local-reassurance-20261019/review.json'));const selected=source.rows.filter(r=>{const t=r.thread.at(-1);return t.direction==='inbound'&&!t.metadata?.partnership_review?.reviewed_at});await fs.writeFile(dir+'/review.json',JSON.stringify({at:source.at,rows:selected},null,2));const names=['FRED SKOGLAND','JOSIE MONIZ','MARGARET ANNE LINDZON','Shannon Hicks','Hey John','LUBA HENDERSON','Steve LoPresti','CHANNI BAINS','KATHY CHIECHI','ANKUR MAHAJAN','KELLY BERGER','JESSYCA ALLISON SCOTT','JOYCE C KWOK','Danica Parilac','ADAM WILSON','FELIX XIA'];const out=[];const norm=v=>String(v||'').replace(/\D/g,'').slice(-10);
for(const r of selected.filter(r=>names.includes(r.contact.name))){const c=r.contact;const peers=(await db('market_contacts',{phone:'ilike.*'+norm(c.phone).slice(-4)+'*'})).filter(x=>norm(x.phone)===norm(c.phone));const sms=await db('sms_messages',{or:`(from_number.eq.${c.phone},to_number.eq.${c.phone})`,order:'created_at.desc',limit:'10'});const calls=await db('call_recordings',{phone_number:'eq.'+c.phone,order:'created_at.desc',limit:'5'});out.push({...r,peers,sms,calls});console.log(JSON.stringify({name:c.name,id:c.id,city:c.city,company:c.company,email:c.email,peers:peers.map(p=>({id:p.id,name:p.name,dnc:p.do_not_contact,suppressed:p.cross_channel_suppressed_at})),sms:sms.slice(0,2).map(t=>({at:t.created_at,body:t.body})),calls:calls.map(c=>({at:c.created_at,transcript:c.transcript}))}));}
await fs.writeFile(dir+'/preflight.json',JSON.stringify(out,null,2));const d=selected.find(r=>r.contact.name==='Danica Parilac');const url=d.thread.at(-1).notes.match(/https:[^\]\s]+/)[0];const res=await fetch(url);if(!res.ok)throw Error('vCard read failed');const vcard=await res.text();await fs.writeFile(dir+'/danica.vcf',vcard);console.log(JSON.stringify({danica_vcard:vcard}));
